INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at, content_type)
VALUES ('Accessibilité des sites de vente en ligne : votre entreprise est-elle concernée ?', 'accessibilite-site-internet', (SELECT id FROM service_categories WHERE slug = 'creation-web'), 'Site internet et conformité', 'Depuis le 28 juin 2025, la vente en ligne doit être accessible aux personnes en situation de handicap. Mais la plupart des TPE sont dispensées : voici comment savoir si vous l''êtes, et les premiers gestes utiles.', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>Depuis le 28 juin 2025, une directive européenne impose que certains produits et services soient accessibles aux personnes en situation de handicap. Le commerce électronique en fait partie.</li> <li>Les entreprises de moins de 10 salariés, avec un chiffre d''affaires annuel ou un total de bilan inférieur à 2 millions d''euros, n''ont aucune obligation d''accessibilité pour leurs services. C''est le cas de la plupart des TPE.</li> <li>Au-delà de ces seuils, un site de vente en ligne doit être perceptible, utilisable, compréhensible et robuste, et l''entreprise doit publier des informations sur sa conformité.</li> </ul> </div> <p>Un client malvoyant qui utilise un lecteur d''écran, une personne qui ne peut pas se servir d''une souris, un client âgé qui agrandit le texte sur son téléphone : tous doivent pouvoir commander sur un site de vente en ligne. C''est l''objet de la directive européenne sur l''accessibilité des produits et des services, appliquée en France depuis le 28 juin 2025.</p> <p>Votre entreprise est-elle concernée ? Ce guide vous aide à le savoir, à partir de la fiche de la DGCCRF, l''administration chargée de la plupart des contrôles.</p> <h2>Qui est concerné ?</h2> <p>La directive vise des produits (ordinateurs, smartphones, terminaux de paiement, bornes en libre-service, téléviseurs, liseuses) et des services. Pour une TPE ou une PME de La Réunion, le service qui compte le plus est <strong>le commerce électronique</strong> : la vente de produits ou de services sur un site ou une application.</p> <p>Les autres services visés sont la téléphonie, l''accès aux médias audiovisuels, certains éléments des services de transport (sites, applications, billets électroniques, informations), les services bancaires aux consommateurs, les livres numériques et les appels au numéro d''urgence européen 112.</p> <table class="table-article"> <thead><tr><th>Votre situation</th><th>Ce que dit la DGCCRF</th></tr></thead> <tbody> <tr><td>Moins de 10 salariés et chiffre d''affaires annuel ou total de bilan inférieur à 2 millions d''euros, vous vendez un service (dont la vente en ligne)</td><td>Aucune obligation d''accessibilité ne s''impose à vous</td></tr> <tr><td>Mêmes seuils, vous fabriquez, importez ou distribuez un produit visé</td><td>Vous pouvez déroger aux obligations sans avoir à vous justifier</td></tr> <tr><td>Au-delà de ces seuils, vous vendez en ligne</td><td>Votre site ou votre application doit respecter les exigences d''accessibilité</td></tr> <tr><td>La mise en conformité changerait la nature même du service, ou serait une charge disproportionnée</td><td>Une exemption est possible, mais il faut la déclarer et pouvoir la justifier</td></tr> </tbody> </table> <h2>Votre entreprise est-elle concernée ? 4 questions</h2> <ol class="etapes"> <li><strong>Vendez-vous en ligne ?</strong> Un site vitrine qui présente votre activité, sans commande ni paiement, ne relève pas du commerce électronique. Une boutique en ligne, un système de réservation payante ou une vente par application, oui.</li> <li><strong>Combien de salariés employez-vous ?</strong> Le seuil est de 10 salariés.</li> <li><strong>Quel est votre chiffre d''affaires annuel, ou votre total de bilan ?</strong> Le seuil est de 2 millions d''euros. Il faut être sous les deux seuils, effectif et chiffre d''affaires ou bilan, pour être dispensé.</li> <li><strong>Votre site existait-il avant le 28 juin 2025 ?</strong> Cela ne change rien : la DGCCRF précise qu''un site ou une application n''est pas un « produit » au sens de la directive, et ne bénéficie donc pas du délai accordé aux produits déjà en service.</li> </ol> <div class="encadre-exemple"> <p class="encadre-titre">Exemple (cas fictif) : deux boutiques en ligne de Saint-Denis</p> <p>Une épicerie fine de 4 salariés, qui réalise 400 000 € de chiffre d''affaires, vend ses paniers en ligne : elle est sous les deux seuils, aucune obligation ne s''impose à elle. Un distributeur de matériel de 25 salariés vend aussi en ligne : il dépasse le seuil d''effectif, son site doit être accessible et il doit publier des informations sur sa conformité.</p> </div> <h2>Ce que la loi demande à un site de vente en ligne</h2> <p>Pour les entreprises concernées, la DGCCRF résume les exigences en quatre principes. Le site ou l''application doit être :</p> <ul class="checklist"> <li><strong>Perceptible</strong> : un équivalent textuel pour tout contenu qui n''est pas du texte (une image, une icône), et un contenu qui peut être présenté autrement sans perte d''information, par exemple avec une mise en page simplifiée.</li> <li><strong>Utilisable</strong> : des repères pour naviguer et trouver le contenu, toutes les fonctions accessibles au clavier, assez de temps pour lire et agir, et aucun contenu susceptible de provoquer des crises d''épilepsie.</li> <li><strong>Compréhensible</strong> : des pages qui fonctionnent de manière prévisible, et une aide pour corriger les erreurs de saisie dans les formulaires.</li> <li><strong>Robuste</strong> : une bonne compatibilité avec les navigateurs et les technologies d''assistance, comme les lecteurs d''écran.</li> </ul> <p>L''entreprise doit aussi publier des informations sur la conformité de son service (la DGCCRF cite l''exemple des rapports d''audit RGAA, le référentiel français d''accessibilité), mettre en place un suivi, corriger les défauts constatés et proposer une assistance joignable par des moyens accessibles. La liste complète des exigences figure dans l''arrêté du 9 octobre 2023.</p> <h2>Les premiers gestes, même si vous n''êtes pas obligé</h2> <p>Une TPE dispensée n''a rien à déclarer. Mais un site plus facile à utiliser sert tous les clients, et ces gestes simples reprennent les principes ci-dessus :</p> <ol class="etapes"> <li><strong>Décrivez vos images</strong> : un texte alternatif court pour chaque photo de produit (« Panier garni : rhum arrangé, confiture de goyave, vanille »).</li> <li><strong>Essayez votre site sans souris</strong> : avec la seule touche Tab, pouvez-vous aller jusqu''au paiement ?</li> <li><strong>Vérifiez la lisibilité</strong> : un texte assez grand, bien contrasté avec le fond, qui reste lisible quand on agrandit l''affichage sur téléphone.</li> <li><strong>Rendez vos formulaires clairs</strong> : chaque champ a une étiquette, et un message d''erreur dit ce qu''il faut corriger.</li> <li><strong>Sous-titrez vos vidéos</strong>, surtout celles qui présentent vos produits ou expliquent une commande.</li> </ol> <h2>Exemptions et déclaration</h2> <p>Hors cas des petites entreprises, une entreprise peut invoquer une exemption si la mise en conformité changerait fondamentalement la nature du service, ou représenterait une charge disproportionnée, selon les critères de l''annexe à l''article D. 412-60 du code de la consommation. Elle doit alors en informer l''autorité de surveillance et pouvoir présenter, sur demande, un dossier technique qui justifie l''exemption.</p> <p>La déclaration se fait en ligne, sur la démarche « Déclaration de non-conformité ou invocation d''une exemption aux obligations d''accessibilité numérique ». À La Réunion, l''interlocuteur est la direction départementale chargée de la protection des populations du siège de l''entreprise.</p> <h2>Contrôles et sanctions</h2> <p>Les contrôles ont commencé dès le 28 juin 2025, notamment à la suite de signalements. Les agents peuvent exiger une mise en conformité, éventuellement avec une astreinte et une mesure de publicité. Les manquements sont des contraventions de 5e classe : la DGCCRF indique des amendes de 7 500 €, qui peuvent se cumuler selon le nombre d''infractions constatées.</p> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>Un site e-commerce sur mesure coûte de 2 490 € à 4 900 € selon le niveau. Le diagnostic gratuit permet de faire le point sur votre projet de vente en ligne. Voir aussi notre guide <a href="/blog/rgpd-tpe-essentiel">RGPD pour une TPE : l''essentiel en 7 étapes</a>.</p> <p><a href="/services#sites-web" class="encadre-lien">Voir l''offre Sites web</a> · <a href="/diagnostic" class="encadre-lien">Réserver un diagnostic gratuit</a></p> </div> <h2>Questions fréquentes</h2> <h3>Mon site vitrine doit-il être accessible ?</h3> <p>Un site qui présente votre activité sans permettre de commander ni de payer ne relève pas du commerce électronique visé par la directive. Les bonnes pratiques d''accessibilité restent utiles pour tous vos visiteurs.</p> <h3>Je suis micro-entrepreneur et je vends en ligne : dois-je faire un audit ?</h3> <p>Si vous employez moins de 10 salariés et que votre chiffre d''affaires annuel ou votre total de bilan est inférieur à 2 millions d''euros, aucune obligation d''accessibilité ne s''impose à vos services, selon la DGCCRF. Aucun audit n''est donc exigé.</p> <h3>Les plateformes comme les places de marché sont-elles concernées ?</h3> <p>Le commerce électronique est visé, quelle que soit sa forme. Si vous vendez sur une place de marché, c''est l''opérateur de la plateforme qui conçoit et fournit le site ; renseignez-vous auprès de lui sur ce qui relève de votre responsabilité.</p> <div class="article-sources"> <p class="encadre-titre">Sources</p> <ul> <li><a href="https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/professionnels-vos-produits-et-services-doivent-etre-conformes-la-directive-accessibilite" target="_blank" rel="noopener">DGCCRF : « Professionnels : vos produits et services doivent être conformes à la directive Accessibilité »</a>, fiche du 13 novembre 2025.</li> <li><a href="https://www.legifrance.gouv.fr/jorf/id/JORFTEXT000048178413" target="_blank" rel="noopener">Légifrance : textes du 9 octobre 2023 sur l''accessibilité des produits et services</a>.</li> <li><a href="https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000048180497" target="_blank" rel="noopener">Légifrance : annexe à l''article D. 412-60 du code de la consommation</a>.</li> <li><a href="https://www.demarches-simplifiees.fr/commencer/exemption-accessibilite-num" target="_blank" rel="noopener">Démarches simplifiées : déclaration de non-conformité ou d''exemption</a>.</li> <li>Grille tarifaire DIGITA : <a href="/tarifs">page Tarifs</a>, consultée le 9 novembre 2026.</li> </ul> </div>', 'Accessibilité numérique : votre site est-il concerné ?', 'Directive accessibilité en vigueur depuis le 28 juin 2025 : qui doit rendre son site de vente accessible, l''exemption des TPE, les exigences et les sanctions.', 'accessibilité numérique, directive accessibilité, European Accessibility Act, site e-commerce accessible, RGAA, DGCCRF', '/assets/images/blog/accessibilite-site-internet.webp', '/assets/images/blog/accessibilite-site-internet.webp', 'draft', NOW(), NOW(), 'guide')
ON CONFLICT (slug) DO NOTHING;
